using System;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MadnessSurgeAction", menuName = "Data/Battle/Battle Actions/Enemy/MadnessSurge Action")]
public class MadnessSurgeAction : PurifyCorruptDiceAmountBasedAction
{
	[Header("Madness Surge")]
	[SerializeField]
	private float delayToStartCorruptedLightningAction;

	[Header("Description")]
	[SerializeField]
	private BattleAction corruptAction;

	public BattleAction CorruptAction => corruptAction;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		return true;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		RandomAllTargetsLightningAction randomAllTargetsLightningAction = purifyCorruptAction as RandomAllTargetsLightningAction;
		if (IsVFXEnabled())
		{
			GameObject vfx = GetVFX();
			ParticleEmissionController particleEmissionController = vfx.GetComponent<ParticleEmissionController>();
			particleEmissionController.SetActive(value: false);
			Action beforeDelayAction = delegate
			{
				particleEmissionController.SetActive(value: true);
				particleEmissionController.RewindParticles();
				PlayLoopableSFX();
			};
			Action afterLightningAction = delegate
			{
				particleEmissionController.SetActive(value: false);
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(vfx, 2f);
				StopLoopableSFX();
			};
			randomAllTargetsLightningAction.CastVariableAndTimesAmountWithActionAndDelayToStart(PurifyCounter(checkConditionToBeCastedOrPreview: false), amount, source, delayToStartCorruptedLightningAction, afterLightningAction, null, beforeDelayAction);
		}
		else
		{
			randomAllTargetsLightningAction.CastVariableAndTimesAmount(PurifyCounter(checkConditionToBeCastedOrPreview: false), amount, source);
		}
	}
}
